package dev.goforge.containers;
import org.junit.Test;
import java.nio.file.*;
import java.util.List;
import static org.junit.Assert.*;
public class KubernetesCommandsTest {
    private final KubernetesCommands.Resource pod=new KubernetesCommands.Resource("Pod","fixture","sample","id-1","Running");
    @Test public void requiresExplicitContextAndNamespaceAndNoCrossNamespaceSelection(){assertThrows(IllegalArgumentException.class,()->KubernetesCommands.inventory("kubectl","","fixture"));assertThrows(IllegalArgumentException.class,()->KubernetesCommands.inventory("kubectl","ctx","--all"));assertThrows(IllegalArgumentException.class,()->KubernetesCommands.describe("kubectl","ctx","other",pod));}
    @Test public void portForwardCanOnlyBindLoopbackAndUsesValidatedPorts(){var command=KubernetesCommands.forward("kubectl","ctx","fixture",pod,8080,80);assertTrue(command.contains("--address=127.0.0.1"));assertEquals("8080:80",command.getLast());assertThrows(IllegalArgumentException.class,()->KubernetesCommands.forward("kubectl","ctx","fixture",pod,0,80));}
    @Test public void diffStatusOneMeansChangesButFailuresCancellationAndTruncationBlockApply(){assertTrue(KubernetesCommands.diffSuccessful(0,false,false,false));assertTrue(KubernetesCommands.diffSuccessful(1,false,false,false));assertFalse(KubernetesCommands.diffSuccessful(2,false,false,false));assertFalse(KubernetesCommands.diffSuccessful(1,true,false,false));assertFalse(KubernetesCommands.diffSuccessful(1,false,false,true));}
    @Test public void manifestSnapshotIsImmutableAndChangesInvalidateApproval()throws Exception{Path root=Files.createTempDirectory("goforge-k8s-");Path file=root.resolve("file.yaml");try{Files.writeString(file,"kind: Pod\n");var snapshot=KubernetesCommands.readManifest(root,file);byte[] bytes=snapshot.bytes();bytes[0]='X';assertEquals('k',snapshot.bytes()[0]);snapshot.requireUnchanged();Files.writeString(file,"kind: Service\n");assertThrows(IllegalStateException.class,snapshot::requireUnchanged);}finally{Files.deleteIfExists(file);Files.delete(root);}}
    @Test public void deletionCarriesAtomicUidPreconditionAndExactNamespacedApiPath(){var options=com.google.gson.JsonParser.parseString(KubernetesCommands.deleteOptions(pod)).getAsJsonObject();assertEquals("id-1",options.getAsJsonObject("preconditions").get("uid").getAsString());var command=KubernetesCommands.delete("kubectl","ctx","fixture",pod,Path.of("/tmp/own.json"));assertTrue(command.contains("/api/v1/namespaces/fixture/pods/sample"));assertTrue(command.contains("--raw"));assertFalse(command.contains("--all"));}
    @Test public void resourceOutputKeepsIdentityAndEmptyList(){assertEquals(List.of(),KubernetesCommands.resources("{\"items\":[]}"));var row=KubernetesCommands.resources("{\"items\":[{\"kind\":\"Pod\",\"metadata\":{\"name\":\"sample\",\"namespace\":\"fixture\",\"uid\":\"id-1\"},\"status\":{\"phase\":\"Running\"}}]}").getFirst();assertEquals(pod,row);assertThrows(IllegalArgumentException.class,()->KubernetesCommands.resources("{}"));}
}
